# ==== Load required packages ====
# Reusing the package set from the original authors' script inputs/analyses_final_rev1.R
library(esc)        # effect size calculation (esc_f)
library(psych)      # reliability analysis and descriptives (alpha, describe, describeBy)
library(ggplot2)    # plotting (figures)
library(dplyr)      # data manipulation (recode)
library(effectsize) # eta_squared
library(pwr)        # power analysis
library(emmeans)    # planned contrasts / emtrends
library(MBESS)      # ci.pvaf for confidence intervals of eta-squared
library(metafor)    # fixed-effects moderator model (Lakens, 2022)
library(jsonlite)   # write outputs/results.json

# Helper to accumulate results for outputs/results.json
.results <- list()
add_result <- function(id, value = NULL, step = NULL, table = NULL, file = NULL, note = NULL) {
  entry <- list(id = id, step = step)
  if (!is.null(value)) entry$value <- unname(value)
  if (!is.null(table)) entry$table <- table
  if (!is.null(file)) entry$file <- file
  if (!is.null(note)) entry$note <- note
  .results[[id]] <<- entry
}

# Formatting helpers for tables (matching the paper's presentation)
fmt2 <- function(x) format(round(x, 2), nsmall = 2)     # e.g. "1.88"
fmt3 <- function(x) format(round(x, 3), nsmall = 3)     # e.g. "0.420"
fmtp <- function(p) paste0(".", sprintf("%03d", round(p * 1000)))  # e.g. ".192"

