# ==== A01 [analysis]: Compute the original negative-expectation effect size by deriving f, eta-square… ====
# Summary:
#   Compute the original negative-expectation effect size by deriving f, eta-squared and the
#   90% CI from the reported F(1,156)=12.09, MSE=3.30, p=.001, r^2=.07 and N=160 using
#   esc::esc_f and MBESS::ci.pvaf.
# Source quote:
#   ""[t]he affective reactions of the negative-expectation participants were less positive
#   than those of the no-expectation participants, regardless of their level of need for
#   cognition, F(1, 156) = 12.09, MSE = 3.30, p = .001, r² = .07", f = 0.270, η² = .07, 90%
#   CI [.02, .14] (p. 317)"
# Inputs: inputs/analyses_final_rev1.R
# Depends on: L01, L02, L03, L04
# Produces: T008, T009, T010, T011, T012, T013, T014, T015, T016
# Reported values from the original study (Geers & Lassiter, 2003), used as inputs.
orig_n <- 160
# Negative-expectation effect: F(1,156)=12.09, MSE=3.30, p=.001, r^2=.07
neg_F <- 12.09
neg_MSE <- 3.30
neg_p <- 0.001
neg_r2 <- 0.07
neg_df1 <- 1
neg_df2 <- 156
# f via esc::esc_f (reusing logic from inputs/analyses_final_rev1.R line 30)
f_neg <- esc::esc_f(f = neg_F, totaln = orig_n, es.type = "f")$es
# ASSUMPTION: esc::esc_f(es.type="f") returns f = 0.2749 for F=12.09, N=160, while the paper
# reports f = 0.270. The authors' own script (inputs/analyses_final_rev1.R) computes f with
# esc_f, so we report the computed value (0.2749); the paper likely rounded it to 2 decimals (0.27).
# eta^2 derived from f (eta^2 = f^2 / (1 + f^2)) as reported in the paper (eta^2 = .07)
eta2_neg <- f_neg^2 / (1 + f_neg^2)
# 90% CI for eta^2 via MBESS::ci.pvaf (reusing inputs/analyses_final_rev1.R lines 34-40)
ci_neg <- MBESS::ci.pvaf(F.value = neg_F, df.1 = neg_df1, df.2 = neg_df2, N = orig_n, conf.level = .90)
ci_neg_low <- ci_neg$Lower.Limit.Proportion.of.Variance.Accounted.for
ci_neg_high <- ci_neg$Upper.Limit.Proportion.of.Variance.Accounted.for

add_result("T008", value = orig_n, step = "A01")
add_result("T009", value = neg_F, step = "A01")
add_result("T010", value = neg_MSE, step = "A01")
add_result("T011", value = neg_p, step = "A01")
add_result("T012", value = neg_r2, step = "A01")
add_result("T013", value = f_neg, step = "A01")
add_result("T014", value = eta2_neg, step = "A01")
add_result("T015", value = ci_neg_low, step = "A01")
add_result("T016", value = ci_neg_high, step = "A01")

# ==== A02 [analysis]: Compute the original expectation x NFC interaction effect size by deriving f, e… ====
# Summary:
#   Compute the original expectation x NFC interaction effect size by deriving f, eta-
#   squared and the 90% CI from the reported F(1,154)=6.40, MSE=3.21, p=.01, r^2=.04 and
#   N=160 using esc::esc_f and MBESS::ci.pvaf.
# Source quote:
#   ""relative to no-expectation participants, the affective reactions of those in the
#   positive-expectation condition became more positive as the need for cognition decreased
#   (i.e., an assimilation effect), and less positive as level of need for cognition
#   increased (i.e., a contrast effect), F(1, 154) = 6.40, MSE = 3.21, p = .01, r² = .04", f
#   = 0.200, η² = .04, 90% CI [.005, .10] (p. 318, N = 160)"
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A01
# Produces: T001, T002, T003, T017, T018, T019, T020, T021, T022, T023, T024
# Reported values from the original study (interaction effect), used as inputs.
int_F <- 6.40
int_MSE <- 3.21
int_p <- 0.01
int_r2 <- 0.04
int_df1 <- 1
int_df2 <- 154
# f via esc::esc_f (reusing inputs/analyses_final_rev1.R line 18)
f_int <- esc::esc_f(f = int_F, totaln = orig_n, es.type = "f")$es
# eta^2 derived from f (eta^2 = f^2 / (1 + f^2)) as reported (eta^2 = .04)
eta2_int <- f_int^2 / (1 + f_int^2)
# 90% CI via MBESS::ci.pvaf (reusing inputs/analyses_final_rev1.R lines 20-26)
ci_int <- MBESS::ci.pvaf(F.value = int_F, df.1 = int_df1, df.2 = int_df2, N = orig_n, conf.level = .90)
ci_int_low <- ci_int$Lower.Limit.Proportion.of.Variance.Accounted.for
ci_int_high <- ci_int$Upper.Limit.Proportion.of.Variance.Accounted.for

add_result("T001", value = eta2_int, step = "A02")
add_result("T002", value = ci_int_low, step = "A02")
add_result("T003", value = ci_int_high, step = "A02")
add_result("T017", value = int_F, step = "A02")
add_result("T018", value = int_MSE, step = "A02")
add_result("T019", value = int_p, step = "A02")
add_result("T020", value = int_r2, step = "A02")
add_result("T021", value = f_int, step = "A02")
add_result("T022", value = eta2_int, step = "A02")
add_result("T023", value = ci_int_low, step = "A02")
add_result("T024", value = ci_int_high, step = "A02")

# ==== A03 [analysis]: Compute the total sample size needed to achieve 95% power for the smaller effec… ====
# Summary:
#   Compute the total sample size needed to achieve 95% power for the smaller effect of
#   f=0.2 using pwr.anova.test with 3 groups (390 participants).
# Source quote:
#   "To achieve 95% power for the smaller of these two effects of f = 0.2, we would have
#   needed 390 participants."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A02
# Produces: T025
# Reusing inputs/analyses_final_rev1.R line 46: pwr.anova.test(3, n=NULL, f=0.2, power=.95)$n * 3
n_per_group <- pwr::pwr.anova.test(k = 3, n = NULL, f = 0.2, power = .95)$n
total_needed <- ceiling(n_per_group * 3)   # round up to 390 participants
add_result("T025", value = total_needed, step = "A03")

# ==== A04 [analysis]: Round the required sample size up to N=400 and compute the multiple of the orig… ====
# Summary:
#   Round the required sample size up to N=400 and compute the multiple of the original
#   sample size (400/160 = 2.5).
# Source quote:
#   "We rounded this number to N = 400 (see https://osf.io/6ua4s for the preregistered power
#   analysis code), which corresponds to 2.5 times the original sample size."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A03
# Produces: T026, T027
target_n <- 400
multiple_original <- target_n / orig_n   # 400 / 160 = 2.5
add_result("T026", value = target_n, step = "A04")
add_result("T027", value = multiple_original, step = "A04")

# ==== A05 [transform]: Load the raw data, keep only interview-mode rows, recode -9 to missing, compute… ====
# Summary:
#   Load the raw data, keep only interview-mode rows, recode -9 to missing, compute the
#   affect index as the mean of the three affect items (BK01_01..03), compute the NFC score
#   as the mean of the 16 German NFC items, recode the experimental condition (RD01) into
#   positive/negative/none, and apply the exclusion criteria retaining only participants
#   with non-missing NFC, affect index and experimental condition.
# Source quote:
#   "At first, the preregistered exclusion criteria were applied. Participants were excluded
#   if values for any of the following variables were not available: Need for cognition,
#   affect index, experimental group (assigned automatically during the experiment)."
# Inputs: inputs/gl2003-replication-raw-2023-03-28.csv, inputs/analyses_final_rev1.R
# Depends on: L01
# Produces: T028, T030
# Reusing the processing steps from inputs/analyses_final_rev1.R (lines 57-113).
ds <- raw_data[raw_data$MODE == "interview", ]
# "replace -9 with NAs": original authors remove rows where NC01_01 == -9
ds <- ds[ds$NC01_01 != -9, ]
# affect index = mean of the three affect items
ds$ai <- rowMeans(cbind(ds$BK01_01, ds$BK01_02, ds$BK01_03))
# NFC score = mean of the 16 German NFC items (Bless et al., 1994)
nfc_items <- c("NC01_01", "NC01_02", "NC01_03", "NC01_09", "NC01_12", "NC01_14",
               "NC01_15", "NC01_16", "NC01_17", "NC01_19", "NC01_22", "NC01_23",
               "NC01_28", "NC01_29", "NC01_30", "NC01_31")
ds$nfc <- rowMeans(cbind(ds[, nfc_items]), na.rm = FALSE)
# experimental condition
ds$expectation <- dplyr::recode(ds$RD01, "1" = "positive", "2" = "negative", "3" = "none")
# exclusion criteria: non-missing NFC, affect index, experimental group
ds <- ds[!is.na(ds$nfc), ]
ds <- ds[!is.na(ds$ai), ]
ds <- ds[!is.na(ds$expectation), ]

n_rep <- nrow(ds)
add_result("T028", value = n_rep, step = "A05")
add_result("T030", value = n_rep, step = "A05")

# ==== A06 [analysis]: Compute the achieved statistical power for f=0.2 with the achieved sample size,… ====
# Summary:
#   Compute the achieved statistical power for f=0.2 with the achieved sample size, the
#   detectable effect size at 95% power, and the achieved power for the original f=0.200,
#   using pwr.anova.test with 3 groups.
# Source quote:
#   "Achieved power was thus 81.37% for f = 0.2. This sample size is sufficient to detect
#   effects of f = 0.249 with 95% power. The achieved power for the original effect size of
#   f = 0.200 was 81.37%."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T029, T031, T032
# Reusing inputs/analyses_final_rev1.R lines 123-125.
pwr_achieved <- pwr::pwr.anova.test(k = 3, n = n_rep / 3, f = 0.2, power = NULL)$power * 100  # 81.37%
f_detectable <- pwr::pwr.anova.test(k = 3, n = n_rep / 3, f = NULL, power = .95)$f           # 0.249
add_result("T029", value = pwr_achieved, step = "A06")
add_result("T031", value = f_detectable, step = "A06")
add_result("T032", value = pwr_achieved, step = "A06")

# ==== A07 [analysis]: Compute age descriptives: count participants who reported age, count missing va… ====
# Summary:
#   Compute age descriptives: count participants who reported age, count missing values, and
#   compute mean, SD, min and max age.
# Source quote:
#   "Only 138 participants reported their age (114 missing values). The reported mean age
#   was M = 47.11 (SD = 16.48) with a range from 19 to 77."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T033, T034, T035, T036, T037, T038
# Reusing inputs/analyses_final_rev1.R line 128: psych::describe(as.numeric(ds$SD01s))
age <- as.numeric(ds$SD01s)
n_age <- sum(!is.na(age))
n_age_missing <- sum(is.na(age))
age_mean <- mean(age, na.rm = TRUE)
age_sd <- sd(age, na.rm = TRUE)
age_min <- min(age, na.rm = TRUE)
age_max <- max(age, na.rm = TRUE)
add_result("T033", value = n_age, step = "A07")
add_result("T034", value = n_age_missing, step = "A07")
add_result("T035", value = age_mean, step = "A07")
add_result("T036", value = age_sd, step = "A07")
add_result("T037", value = age_min, step = "A07")
add_result("T038", value = age_max, step = "A07")

