# ==== A10 [analysis]: Compute Cronbach's alpha for the 3-item affect index in the replication sample … ====
# Summary:
#   Compute Cronbach's alpha for the 3-item affect index in the replication sample (with 95%
#   CI) and report the original study's alpha of .93.
# Source quote:
#   "Responses of those items were averaged to gain a single affect index, which reached an
#   internal consistency of α = .93. ... we analyzed the internal consistency of our affect
#   index items and found α = .96 (95% CI [0.95, 0.97])."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T050, T051, T052, T053
# Reusing inputs/analyses_final_rev1.R line 134: psych::alpha(cbind(ds$BK01_01, ...))
alpha_ai <- psych::alpha(cbind(ds$BK01_01, ds$BK01_02, ds$BK01_03))
add_result("T050", value = 0.93, step = "A10")                          # original alpha (reported)
add_result("T051", value = alpha_ai$total$raw_alpha, step = "A10")      # replication alpha
add_result("T052", value = alpha_ai$feldt$lower.ci$raw_alpha, step = "A10")   # 95% CI lower (Feldt)
add_result("T053", value = alpha_ai$feldt$upper.ci$raw_alpha, step = "A10")   # 95% CI upper (Feldt)

# ==== A11 [analysis]: Compute Cronbach's alpha for the 16-item German NFC scale in the replication sa… ====
# Summary:
#   Compute Cronbach's alpha for the 16-item German NFC scale in the replication sample with
#   95% CI.
# Source quote:
#   "In our sample and using the scale by Bless et al. (1994), we found a value of α = 0.85
#   (95% CI [0.83, 0.88], 16 items)."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T054, T055, T056, T057
# Reusing inputs/analyses_final_rev1.R lines 137-154: psych::alpha(cbind(ds$NC01_xx, ...))
alpha_nfc <- psych::alpha(as.data.frame(ds[, nfc_items]))
add_result("T054", value = alpha_nfc$total$raw_alpha, step = "A11")     # replication alpha
add_result("T055", value = alpha_nfc$feldt$lower.ci$raw_alpha, step = "A11")   # 95% CI lower (Feldt)
add_result("T056", value = alpha_nfc$feldt$upper.ci$raw_alpha, step = "A11")   # 95% CI upper (Feldt)
add_result("T057", value = length(nfc_items), step = "A11")             # 16 items

# ==== A12 [analysis]: Run a one-way ANOVA of remembered expectation (BK03_07) on the induced expectat… ====
# Summary:
#   Run a one-way ANOVA of remembered expectation (BK03_07) on the induced expectation
#   condition and report F, p and significance.
# Source quote:
#   "A one-way ANOVA revealed a significant influence of induced expectation on remembered
#   expectations, F(2, 249) = 3.90, p = .021."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T058, T059, T060
# Reusing inputs/analyses_final_rev1.R lines 159-160.
mc <- aov(BK03_07 ~ expectation, data = ds)
mc_summary <- summary(mc)[[1]]
mc_F <- mc_summary$`F value`[1]
mc_p <- mc_summary$`Pr(>F)`[1]
add_result("T058", value = mc_F, step = "A12")
add_result("T059", value = mc_p, step = "A12")
add_result("T060", value = ifelse(mc_p < .05, "significant", "not significant"), step = "A12")

# ==== A13 [analysis]: Run Tukey HSD post-hoc comparisons of remembered expectation means between the … ====
# Summary:
#   Run Tukey HSD post-hoc comparisons of remembered expectation means between the positive
#   and negative expectation groups; report group means, SDs, Ns, the mean difference, its
#   95% CI and the p-value.
# Source quote:
#   "only a significant difference between the positive (M = 5.21, SD = 2.00, N = 75) and
#   the negative (M = 4.35, SD = 1.94, N = 94) expectation group was found (Δ = 0.862, 95%
#   CI [0.127, 1.597], p = .017)."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T061, T062, T063, T064, T065, T066, T067, T068, T069, T070
# Reusing inputs/analyses_final_rev1.R lines 163-164 (TukeyHSD, describeBy).
tukey_mc <- TukeyHSD(mc)
pos_neg <- tukey_mc$expectation["positive-negative", ]
des_mc <- psych::describeBy(BK03_07 ~ expectation, data = ds)
pos_mc <- des_mc$positive
neg_mc <- des_mc$negative
add_result("T061", value = pos_mc$mean, step = "A13")
add_result("T062", value = pos_mc$sd, step = "A13")
add_result("T063", value = pos_mc$n, step = "A13")
add_result("T064", value = neg_mc$mean, step = "A13")
add_result("T065", value = neg_mc$sd, step = "A13")
add_result("T066", value = neg_mc$n, step = "A13")
add_result("T067", value = pos_neg[["diff"]], step = "A13")
add_result("T068", value = pos_neg[["lwr"]], step = "A13")
add_result("T069", value = pos_neg[["upr"]], step = "A13")
add_result("T070", value = pos_neg[["p adj"]], step = "A13")

