# ==== A15 [analysis]: Create a violin/jitter plot of remembered expectation by induced expectation co… ====
# Summary:
#   Create a violin/jitter plot of remembered expectation by induced expectation condition
#   (Figure 1), with solid lines representing medians.
# Source quote:
#   "A distribution of the data can be seen in Figure 1. Figure 1 Remembered expectation by
#   induced expectation. Solid lines represent medians."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T139
# Reusing inputs/analyses_final_rev1.R lines 176-199 (geom_violin + geom_jitter, medians).
dir.create("outputs/figures", showWarnings = FALSE, recursive = TRUE)
set.seed(1)
p_fig1 <- ggplot(ds, aes(y = BK03_07, x = expectation)) +
  geom_violin(draw_quantiles = .5) +
  geom_jitter(width = .1, height = 0) +
  scale_x_discrete(name = "Remembered Positivity of Expectation",
                   limits = c("negative", "none", "positive")) +
  scale_y_continuous(name = "Induced Expectation", limits = c(1, 9), breaks = seq(1, 9, 1)) +
  theme_bw() +
  theme(panel.border = element_blank(), axis.line = element_line(colour = "black"))
ggsave("outputs/figures/T139.png", p_fig1, scale = 2, height = 800, width = 800, units = "px")
add_result("T139", file = "outputs/figures/T139.png", step = "A15")

# ==== A16 [analysis]: Fit a linear regression of affect index on expectation condition, NFC and their… ====
# Summary:
#   Fit a linear regression of affect index on expectation condition, NFC and their
#   interaction; report the overall model F, p and R-squared and its significance.
# Source quote:
#   "The overall model test was not significant, F(5, 246) = 1.86, p = .103, R2 = 0.036."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T074, T075, T076, T077
# Reusing inputs/analyses_final_rev1.R line 202: lm(ai ~ expectation * nfc, data = ds)
model <- lm(ai ~ expectation * nfc, data = ds)
model_summary <- summary(model)
model_F <- model_summary$fstatistic[1]
model_df1 <- model_summary$fstatistic[2]
model_df2 <- model_summary$fstatistic[3]
model_p <- pf(model_F, model_df1, model_df2, lower.tail = FALSE)
# ASSUMPTION: the computed overall-model p-value is 0.10249, which R rounds to 0.102, while the
# paper reports p = .103 (rounding 0.1025 half-up). We report the exact computed p-value.
model_r2 <- model_summary$r.squared
add_result("T074", value = model_F, step = "A16")
add_result("T075", value = model_p, step = "A16")
add_result("T076", value = model_r2, step = "A16")
add_result("T077", value = ifelse(model_p < .05, "significant", "not significant"), step = "A16")

# ==== A17 [analysis]: Report that none of the model's individual effects were significant (all ps > .… ====
# Summary:
#   Report that none of the model's individual effects were significant (all ps > .143).
# Source quote:
#   "In line with this, none of the model's effects were significant (all ps > .143, see
#   Table 2)."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A16
# Produces: T078, T079
# The smallest p-value among the model's effects (excluding the intercept) is the NFC
# coefficient p = .143, which is the threshold the paper refers to.
coef_pvals <- model_summary$coefficients[-1, "Pr(>|t|)"]   # exclude intercept
min_coef_p <- min(coef_pvals)
add_result("T078", value = min_coef_p, step = "A17")
add_result("T079", value = ifelse(all(coef_pvals > .05), "not significant", "significant"), step = "A17")

# ==== A18 [analysis]: Produce Table 2, the linear regression of affective reaction on expectation, NF… ====
# Summary:
#   Produce Table 2, the linear regression of affective reaction on expectation, NFC and
#   their interaction, reporting the coefficient B, SE, t and p for all terms.
# Source quote:
#   "Table 2 Linear Regression of Affective Reaction on Expectation, NFC, and Their
#   Interaction Coefficient B SE t p Intercept 1.88 1.44 1.31 .192 Expectation (none) 2.53
#   2.10 1.21 .229 Expectation (positive) 1.36 2.04 0.67 .506 NFC 0.42 0.29 1.47 .143
#   Expectation (none) × NFC −0.55 0.42 −1.32 .190 Expectation (positive) × NFC −0.13 0.41
#   −0.32 .750"
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A16
# Produces: T080
# Reference category for expectation is "negative" (see sec1.p49.s6).
coefs <- model_summary$coefficients
row_labels <- c("Intercept", "Expectation (none)", "Expectation (positive)", "NFC",
                "Expectation (none) × NFC", "Expectation (positive) × NFC")
tab2 <- list(
  c("Coefficient", "B", "SE", "t", "p"),
  c(row_labels[1], fmt2(coefs["(Intercept)", "Estimate"]), fmt2(coefs["(Intercept)", "Std. Error"]),
    fmt2(coefs["(Intercept)", "t value"]), fmtp(coefs["(Intercept)", "Pr(>|t|)"])),
  c(row_labels[2], fmt2(coefs["expectationnone", "Estimate"]), fmt2(coefs["expectationnone", "Std. Error"]),
    fmt2(coefs["expectationnone", "t value"]), fmtp(coefs["expectationnone", "Pr(>|t|)"])),
  c(row_labels[3], fmt2(coefs["expectationpositive", "Estimate"]), fmt2(coefs["expectationpositive", "Std. Error"]),
    fmt2(coefs["expectationpositive", "t value"]), fmtp(coefs["expectationpositive", "Pr(>|t|)"])),
  c(row_labels[4], fmt2(coefs["nfc", "Estimate"]), fmt2(coefs["nfc", "Std. Error"]),
    fmt2(coefs["nfc", "t value"]), fmtp(coefs["nfc", "Pr(>|t|)"])),
  c(row_labels[5], fmt2(coefs["expectationnone:nfc", "Estimate"]), fmt2(coefs["expectationnone:nfc", "Std. Error"]),
    fmt2(coefs["expectationnone:nfc", "t value"]), fmtp(coefs["expectationnone:nfc", "Pr(>|t|)"])),
  c(row_labels[6], fmt2(coefs["expectationpositive:nfc", "Estimate"]), fmt2(coefs["expectationpositive:nfc", "Std. Error"]),
    fmt2(coefs["expectationpositive:nfc", "t value"]), fmtp(coefs["expectationpositive:nfc", "Pr(>|t|)"]))
)
add_result("T080", table = tab2, step = "A18")

# ==== A19 [analysis]: Report the residual standard error (2.30 on 246 df) and the adjusted R-squared … ====
# Summary:
#   Report the residual standard error (2.30 on 246 df) and the adjusted R-squared (.017)
#   from the full regression model.
# Source quote:
#   "Residual SE = 2.30 on 246 df. R² = .036, adjusted R² = .017, F(5, 246) = 1.86, p =
#   .103."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A16
# Produces: T081, T082
add_result("T081", value = model_summary$sigma, step = "A19")                # residual SE = 2.30
add_result("T082", value = model_summary$adj.r.squared, step = "A19")        # adjusted R^2 = .017

# ==== A20 [analysis]: Run a two-way ANOVA of affect index on expectation condition and NFC (and their… ====
# Summary:
#   Run a two-way ANOVA of affect index on expectation condition and NFC (and their
#   interaction); report F, p, eta-squared and the 90% CI for the expectation main effect,
#   the NFC main effect and the interaction, and conclude there is no evidence for a group
#   difference nor NFC moderation.
# Source quote:
#   "there was no main effect of expectation condition on the affect index, F(2, 246) =
#   3.00, p = .051, η² = 0.02, 90% CI [0, 0.05], need for cognition F(1, 246) = 1.43, p =
#   .233, η² < 0.01, 90% CI [0, 0.02] or an interaction effect F(2, 246) = 0.92, p = .398,
#   η² < 0.01, 90% CI [0, 0.02]."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T004, T005, T006, T007, T083, T084, T085, T086, T087, T088, T089, T090, T091, T092, T093, T094, T095, T096, T097, T098
# Reusing inputs/analyses_final_rev1.R lines 203-209 (anova + effectsize::eta_squared).
anova_model <- anova(model)
eta2_model <- effectsize::eta_squared(anova_model, partial = FALSE, alternative = "less", ci = .90)

# Extract F, p from the ANOVA table
an_row <- function(name) {
  r <- anova_model[name, ]
  c(F = r[["F value"]], p = r[["Pr(>F)"]])
}
an_expect <- an_row("expectation")
an_nfc <- an_row("nfc")
an_int <- an_row("expectation:nfc")

# Extract eta-squared and 90% CI
es_expect <- eta2_model[eta2_model$Parameter == "expectation", ]
es_nfc <- eta2_model[eta2_model$Parameter == "nfc", ]
es_int <- eta2_model[eta2_model$Parameter == "expectation:nfc", ]

# Expectation main effect
add_result("T083", value = an_expect["F"], step = "A20")
add_result("T084", value = an_expect["p"], step = "A20")
add_result("T085", value = es_expect$Eta2, step = "A20")
add_result("T086", value = es_expect$CI_low, step = "A20")
add_result("T087", value = es_expect$CI_high, step = "A20")
# NFC main effect
add_result("T088", value = an_nfc["F"], step = "A20")
add_result("T089", value = an_nfc["p"], step = "A20")
add_result("T090", value = es_nfc$Eta2, step = "A20")
add_result("T091", value = es_nfc$CI_low, step = "A20")
add_result("T092", value = es_nfc$CI_high, step = "A20")
# Interaction effect
add_result("T093", value = an_int["F"], step = "A20")
add_result("T094", value = an_int["p"], step = "A20")
add_result("T095", value = es_int$Eta2, step = "A20")
add_result("T096", value = es_int$CI_low, step = "A20")
add_result("T097", value = es_int$CI_high, step = "A20")
# Conclusion: no significant effect (all ps >= .051)
add_result("T098", value = ifelse(all(c(an_expect["p"], an_nfc["p"], an_int["p"]) > .05),
                                  "not significant", "significant"), step = "A20")
# Focal replication effect (interaction) from the abstract (sec1.p7.s5)
add_result("T004", value = es_int$Eta2, step = "A20")
add_result("T005", value = es_int$CI_low, step = "A20")
add_result("T006", value = es_int$CI_high, step = "A20")
add_result("T007", value = "no evidence", step = "A20")

# ==== A21 [analysis]: For each expectation condition (positive, negative, none), fit a simple linear … ====
# Summary:
#   For each expectation condition (positive, negative, none), fit a simple linear
#   regression of affect index on NFC and report the slope b, SE, t and p.
# Source quote:
#   "Positive expectations: b = 0.288, se = 0.306, t(73) = 0.94, p = .349 • Negative
#   expectations: b = 0.420, se = 0.275, t(92) = 1.53, p = .130 • Control group (no specific
#   expectations): b = -0.131, se = 0.312, t(81) = -0.420, p = .675."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A05
# Produces: T099, T100, T101, T102, T103, T104, T105, T106, T107, T108, T109, T110, T111
# Reusing inputs/analyses_final_rev1.R lines 212-214 (slopes for the single groups).
slope_pos <- summary(lm(ai ~ nfc, data = ds[ds$expectation == "positive", ]))$coefficients["nfc", ]
slope_neg <- summary(lm(ai ~ nfc, data = ds[ds$expectation == "negative", ]))$coefficients["nfc", ]
slope_none <- summary(lm(ai ~ nfc, data = ds[ds$expectation == "none", ]))$coefficients["nfc", ]
# Positive expectation slope
add_result("T099", value = slope_pos["Estimate"], step = "A21")
add_result("T100", value = slope_pos["Std. Error"], step = "A21")
add_result("T101", value = slope_pos["t value"], step = "A21")
add_result("T102", value = slope_pos["Pr(>|t|)"], step = "A21")
# Negative expectation slope
add_result("T103", value = slope_neg["Estimate"], step = "A21")
add_result("T104", value = slope_neg["Std. Error"], step = "A21")
add_result("T105", value = slope_neg["t value"], step = "A21")
add_result("T106", value = slope_neg["Pr(>|t|)"], step = "A21")
# No-expectation (control) slope
add_result("T107", value = slope_none["Estimate"], step = "A21")
add_result("T108", value = slope_none["Std. Error"], step = "A21")
add_result("T109", value = slope_none["t value"], step = "A21")
add_result("T110", value = slope_none["Pr(>|t|)"], step = "A21")
# Conclusion: none of the slopes significantly different from zero
add_result("T111", value = ifelse(all(c(slope_pos["Pr(>|t|)"], slope_neg["Pr(>|t|)"], slope_none["Pr(>|t|)"]) > .05),
                                   "not significant", "significant"), step = "A21")

