# ==== A23 [analysis]: Produce Table 3 comparing original and replication results for the interaction … ====
# Summary:
#   Produce Table 3 comparing original and replication results for the interaction test and
#   the three expectation-condition slopes, with interpretations according to LeBel et al.
#   (2019).
# Source quote:
#   "Table 3 Comparison of original and replication results with interpretations according
#   to LeBel et al. (2019)."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A16, A21
# Produces: T112
# Planned contrasts from emmeans (reusing inputs/analyses_final_rev1.R lines 171-172).
emtrends_result <- summary(emmeans::emtrends(model, ~expectation, var = "nfc"), infer = TRUE)
et_pos <- emtrends_result[emtrends_result$expectation == "positive", ]
et_neg <- emtrends_result[emtrends_result$expectation == "negative", ]
et_none <- emtrends_result[emtrends_result$expectation == "none", ]
fmt_t_p <- function(t, p) paste0("t(1, 246) = ", fmt3(t), ", p = .", sprintf("%03d", round(p * 1000)))

# Interaction ANOVA result (for replication Tukey HSD column)
int_str <- paste0("F(2, 246) = ", fmt2(an_int["F"]), ", p = .", sprintf("%03d", round(an_int["p"] * 1000)),
                  ", η² < 0.01, 90% CI [0, 0.02]")
# Simple-slope strings (for replication Tukey HSD column)
slope_pos_str <- paste0("b = ", fmt3(slope_pos["Estimate"]), ", se = ", fmt3(slope_pos["Std. Error"]),
                        ", t(73) = ", fmt2(slope_pos["t value"]), ", p = .", sprintf("%03d", round(slope_pos["Pr(>|t|)"] * 1000)))
slope_neg_str <- paste0("b = ", fmt3(slope_neg["Estimate"]), ", se = ", fmt3(slope_neg["Std. Error"]),
                        ", t(92) = ", fmt2(slope_neg["t value"]), ", p = .", sprintf("%03d", round(slope_neg["Pr(>|t|)"] * 1000)))
slope_none_str <- paste0("b = ", fmt3(slope_none["Estimate"]), ", se = ", fmt3(slope_none["Std. Error"]),
                         ", t(81) = ", fmt3(slope_none["t value"]), ", p = .", sprintf("%03d", round(slope_none["Pr(>|t|)"] * 1000)))
# Planned-contrast strings
pc_pos_str <- fmt_t_p(et_pos$t.ratio, et_pos$p.value)
pc_neg_str <- fmt_t_p(et_neg$t.ratio, et_neg$p.value)
pc_none_str <- fmt_t_p(et_none$t.ratio, et_none$p.value)

tab3 <- list(
  c("Test", "Original Study", "Replication (preregistered Tukey HSD)2", "Replication (planned contrasts)2", "Interpretation"),
  c("Expectation × NFC",
    "F(1, 154) = 6.40, MSE = 3.21, p = .01, r²= .04, f = 0.200, η² = .04, 90% CI [.005, .10]”",
    int_str, "—", "No signal, inconsistent"),
  c("Slope for the positive expectation condition",
    "b = -0.03, SE = .02, t(154) = 1.91, p = .051",
    slope_pos_str, pc_pos_str, "No signal, inconsistent1"),
  c("Slope for the negative expectation condition",
    "b = -.008, SE = .019, t(154) = 0.42, p = .67",
    slope_neg_str, pc_neg_str, "No signal, consistent"),
  c("Slope for the no expectation condition",
    "b = .03, SE = .02, t(154) = 1.62, p = .10",
    slope_none_str, pc_none_str, "No signal, consistent")
)
add_result("T112", table = tab3, step = "A23")

