# ==== A26 [analysis]: Convert the focal original (eta2=.04, N=160) and replication (eta2<.01, N=252) … ====
# Summary:
#   Convert the focal original (eta2=.04, N=160) and replication (eta2<.01, N=252) effect
#   sizes to r=sqrt(eta2) and fit a fixed-effects meta-analytic moderator model (Lakens,
#   2022) with study as moderator; report the replication coefficient, QM and p.
# Source quote:
#   "effect sizes for the focal original and replication test were converted from η² to r
#   and compared using a meta-analytical test for moderation by the replication. Thereby,
#   the replication effect was significantly smaller than the original effect. ... The
#   moderator test QM(1) = 4.09, p = .043 indicates the replication effect size differed
#   significantly from the original."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A02, A20
# Produces: T113, T114, T115, T116
# Reusing inputs/analyses_final_rev1.R lines 405-425.
# Original: eta2 = .04 -> r = sqrt(.04); Replication: eta2 < .01 -> r = sqrt(0) (as in authors' code)
d_original <- escalc(measure = "COR", ri = sqrt(0.04), ni = orig_n)
d_replication <- escalc(measure = "COR", ri = sqrt(0.00), ni = n_rep)
metadata_meta <- data.frame(
  yi = c(d_original$yi, d_replication$yi),
  vi = c(d_original$vi, d_replication$vi),
  study = c("original", "replication")
)
res_meta <- rma(yi, vi, mods = ~study, method = "FE", data = metadata_meta, digits = 3)
# Table 4
coefs_meta <- coef(summary(res_meta))
# coefs_meta is a data.frame; extract scalars by row and column
meta_val <- function(row_name, col) coefs_meta[row_name, col]
meta_p <- function(row_name) coefs_meta[row_name, "pval"]
meta_ci_lb <- function(row_name) coefs_meta[row_name, "ci.lb"]
meta_ci_ub <- function(row_name) coefs_meta[row_name, "ci.ub"]
meta_z <- function(row_name) coefs_meta[row_name, "zval"]
meta_se <- function(row_name) coefs_meta[row_name, "se"]
meta_est <- function(row_name) coefs_meta[row_name, "estimate"]
fmt_meta_p <- function(row_name) paste0(".", sprintf("%03d", round(as.numeric(meta_p(row_name)) * 1000)))
tab4 <- list(
  c("Coefficient", "b", "SE", "z", "p", "95% CI"),
  c("Intercept", fmt3(as.numeric(meta_est("intrcpt"))), fmt3(as.numeric(meta_se("intrcpt"))),
    fmt2(as.numeric(meta_z("intrcpt"))), fmt_meta_p("intrcpt"),
    paste0("[.", sprintf("%03d", round(as.numeric(meta_ci_lb("intrcpt")) * 1000)), ", .",
           sprintf("%03d", round(as.numeric(meta_ci_ub("intrcpt")) * 1000)), "]")),
  c("Study (replication)", fmt3(as.numeric(meta_est("studyreplication"))), fmt3(as.numeric(meta_se("studyreplication"))),
    fmt2(as.numeric(meta_z("studyreplication"))), fmt_meta_p("studyreplication"),
    paste0("[-.", sprintf("%03d", round(abs(as.numeric(meta_ci_lb("studyreplication"))) * 1000)), ", -.",
           sprintf("%03d", round(abs(as.numeric(meta_ci_ub("studyreplication"))) * 1000)), "]"))
)
add_result("T113", table = tab4, step = "A26")
add_result("T114", value = ifelse(as.numeric(meta_p("studyreplication")) < .05, "significant", "not significant"), step = "A26")
add_result("T115", value = res_meta$QM, step = "A26")
add_result("T116", value = res_meta$QMp, step = "A26")

