ds$ac3 <- ifelse(ds$IK01_03 == 1, TRUE, FALSE)
ds$ac4 <- ifelse(ds$IK01_04 == 2, TRUE, FALSE)
ds$ac <- apply(cbind(ds$ac1, ds$ac2, ds$ac3, ds$ac4), 1, FUN = "sum")

ac_4 <- sum(ds$ac == 4, na.rm = TRUE)
ac_3 <- sum(ds$ac == 3, na.rm = TRUE)
ac_2 <- sum(ds$ac == 2, na.rm = TRUE)
ac_1 <- sum(ds$ac == 1, na.rm = TRUE)
ac_0 <- sum(ds$ac == 0, na.rm = TRUE)
ac_missing <- sum(is.na(ds$ac))
ac_total <- nrow(ds)
add_result("T119", value = ac_4, step = "A29")
add_result("T120", value = ac_4 / ac_total * 100, step = "A29")
add_result("T121", value = ac_3, step = "A29")
add_result("T122", value = ac_3 / ac_total * 100, step = "A29")
add_result("T123", value = ac_2, step = "A29")
add_result("T124", value = ac_2 / ac_total * 100, step = "A29")
add_result("T125", value = ac_1, step = "A29")
add_result("T126", value = ac_1 / ac_total * 100, step = "A29")
add_result("T127", value = ac_missing, step = "A29")
add_result("T128", value = ac_missing / ac_total * 100, step = "A29")
add_result("T129", value = ifelse(ac_0 == 0, "none", "some"), step = "A29")

# ==== A30 [analysis]: Re-run the main hypothesis model on the 149 participants who answered all four … ====
# Summary:
#   Re-run the main hypothesis model on the 149 participants who answered all four attention
#   check items correctly; report F, p and R-squared.
# Source quote:
#   "Running the main hypothesis's model only on the 149 participants that responded
#   correctly to the four attention check items did not affect the results, F(5, 143) =
#   0.94, p = .459, R² = .032."
# Inputs: inputs/analyses_final_rev1.R
# Depends on: A29
# Produces: T130, T131, T132
# Reusing inputs/analyses_final_rev1.R lines 367-375.
# Use a clean filter (avoid the all-NA row introduced by R's NA logical indexing).
ds_ac <- ds[!is.na(ds$ac) & ds$ac == 4, ]
model_ac <- lm(ai ~ expectation * nfc, data = ds_ac)
model_ac_summary <- summary(model_ac)
model_ac_F <- model_ac_summary$fstatistic[1]
model_ac_df1 <- model_ac_summary$fstatistic[2]
model_ac_df2 <- model_ac_summary$fstatistic[3]
model_ac_p <- pf(model_ac_F, model_ac_df1, model_ac_df2, lower.tail = FALSE)
add_result("T130", value = model_ac_F, step = "A30")
add_result("T131", value = model_ac_p, step = "A30")
add_result("T132", value = model_ac_summary$r.squared, step = "A30")

