# ==== OUT [results]: Collect all reproduced results and write outputs/results.json (format: schemas/… ====
# Summary:
#   Collect all reproduced results and write outputs/results.json (format: schemas/results-
#   output.schema.json); save figures to outputs/figures/<target id>.png
# Depends on: A04, A06, A07, A08, A09, A10, A11, A12, A13, A14, A15, A17, A18, A19, A22, A23, A24, A25, A26, A27, A28, A30, A31, A33
# Produces: T001, ..., T143
# Write outputs/results.json in the required format.
out_results <- lapply(names(.results), function(id) {
  entry <- .results[[id]]
  # keep only the fields that are set (id always present)
  entry[!vapply(entry, is.null, logical(1))]
})
json <- list(results = out_results)
writeLines(jsonlite::toJSON(json, auto_unbox = TRUE, pretty = TRUE, digits = 15), "outputs/results.json")
cat("Wrote outputs/results.json with", length(out_results), "results.\n")
